{"implementation": "def solve(case):
    import json
    payload = case['payload']
    min_size = payload['min_cluster_size']
    clusters = {c['cluster_id']: c for c in payload['clusters']}
    parent = payload['parent']

    # Build children mapping
    children = {cid: [] for cid in clusters}
    root = None
    for cid, p in parent.items():
        if p is None:
            root = cid
        else:
            children[p].append(cid)

    # Compute stability for each cluster (own points from point_exit_lambdas)
    stability = {}
    for cid, c in clusters.items():
        s = sum(l - c['birth_lambda'] for l in c['point_exit_lambdas'])
        stability[cid] = s

    # Prune clusters below min_size, adjust tree
    def prune(node):
        # Recursively prune children, return pruned children
        pruned = []
        for child in children[node]:
            if clusters[child]['size'] >= min_size:
                # keep child, recurse
                pruned.append(child)
                prune(child)
            else:
                # skip this cluster, but its children become children of node
                for grandchild in children[child]:
                    children[node].append(grandchild)
                # remove child from children dict
                children.pop(child, None)
                # adjust parent of grandchild to node
                parent[grandchild] = node
        children[node] = pruned

    if root is not None:
        prune(root)

    # Perform bottom-up selection
    selected = set()
